import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Optimized CUDA kernel with register blocking
cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define BLOCK_SIZE 8

__global__ void matrix_mult_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int bx = blockIdx.x * BLOCK_SIZE;
    int by = blockIdx.y * BLOCK_SIZE;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    float c[BLOCK_SIZE][BLOCK_SIZE] = {{0.0f}};

    // Loop over tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Load tile from A into shared memory
        int a_col = t * TILE_SIZE + tx;
        if (by + ty < N && a_col < N) {
            As[ty][tx] = A[(by + ty) * N + a_col];
        } else {
            As[ty][tx] = 0.0f;
        }

        // Load tile from B into shared memory
        int b_row = t * TILE_SIZE + ty;
        if (b_row < N && bx + tx < N) {
            Bs[ty][tx] = B[b_row * N + (bx + tx)];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial sum using register blocking
        for (int k = 0; k < TILE_SIZE; k++) {
            float a_val = As[ty][k];

            #pragma unroll
            for (int i = 0; i < BLOCK_SIZE; i++) {
                c[i][tx] += a_val * Bs[k][i * BLOCK_SIZE + tx];
            }
        }

        __syncthreads();
    }

    // Write result to global memory
    for (int i = 0; i < BLOCK_SIZE; i++) {
        int row = by + i * BLOCK_SIZE + ty;
        int col = bx + tx;
        if (row < N && col < N) {
